  SHEET_NAME: 'Form Responses 1',   // <-- change if different
  HEADER_ROW: 1,

  // Invoice template (optional: if using a template sheet for PDF)
  INVOICE_TEMPLATE_SHEET: 'InvoiceTemplate', // or null if not using
  INVOICE_OUTPUT_FOLDER_ID: 'YOUR_DRIVE_FOLDER_ID_FOR_PDFS',

  // Email addresses
  INTERNAL_EMAILS: ['info@psdepot.com'],
  DOMTAR_EMAILS: ['domtar-orders@example.com'],
  ACM_EMAILS: ['acm-orders@example.com'],

  // Company info
  COMPANY_NAME: 'Performance Supply Depot LLC',
  COMPANY_EMAIL: 'info@psdepot.com',

  // Tax by location (example)
  TAX_BY_LOCATION: {
    'Dolores': 0.0875,
    'Duboce': 0.0875,
    'Precita': 0.0875,
    'Paradise': 0.0875,
    'SFO': 0.0875
  },

  // Column mapping (must match your sheet headers)
  COLS: {
    timestamp: 'Timestamp',
    location: 'Location',
    contactName: 'Contact Name',
    contactEmail: 'Contact Email',
    itemSku: 'Item SKU',
    itemDesc: 'Item Description',
    qty: 'Quantity',
    sellPrice: 'Sell Price',
    cost: 'Cost',
    vendor: 'Vendor',          // e.g. 'DOMTAR', 'ACM'
    notes: 'Notes',
    poNumber: 'PO Number',
    subtotal: 'Subtotal',
    tax: 'Tax',
    total: 'Total',
    profit: 'Profit',
    margin: 'Margin',
    acmTracking: 'ACM Tracking',
    status: 'Status'
  }
};

/************************************************************
 * ENTRY POINT
 * Trigger: Installable "On form submit" on the response sheet
 ************************************************************/
function onFormSubmit(e) {
  try {
    const sheet = e.range.getSheet();
    if (sheet.getName() !== CFG.SHEET_NAME) return;

    const row = e.range.getRow();
    const headers = getHeaders_(sheet);
    const rowData = getRowObject_(sheet, row, headers);

    // 1) Enrich order (PO, math, tax)
    const enriched = enrichOrder_(rowData);

    // 2) Persist enriched values back to sheet
    writeEnrichedToSheet_(sheet, row, headers, enriched);

    // 3) Vendor routing
    const domtarItems = filterItemsByVendor_([enriched], 'DOMTAR');
    const acmItems = filterItemsByVendor_([enriched], 'ACM');

    // 4) Send internal summary
    sendInternalEmail_(enriched);

    // 5) Send Domtar email (if any)
    if (domtarItems.length) {
      sendDomtarEmail_(domtarItems);
    }

    // 6) Send ACM order (if any)
    if (acmItems.length) {
      const tracking = sendAcmOrderAndGetTracking_(acmItems[0]); //
one row per submit
      if (tracking) {
        sheet.getRange(row, headers[CFG.COLS.acmTracking]).setValue(tracking);
      }
    }

    // 7) Generate invoice PDF + send to customer
    const pdfFile = generateInvoicePdf_(enriched);
    sendCustomerInvoiceEmail_(enriched, pdfFile);

    // 8) Mark status
    sheet.getRange(row, headers[CFG.COLS.status]).setValue('Processed');

  } catch (err) {
    Logger.log('Error in onFormSubmit: ' + err);
  }
}

/************************************************************
 * HEADER / ROW HELPERS
 ************************************************************/
function getHeaders_(sheet) {
  const headerRow = sheet.getRange(CFG.HEADER_ROW, 1, 1,
sheet.getLastColumn()).getValues()[0];
  const map = {};
  headerRow.forEach((h, i) => {
    if (h && typeof h === 'string') {
      map[h.trim()] = i + 1;
    }
  });
  return map;
}

function getRowObject_(sheet, row, headers) {
  const values = sheet.getRange(row, 1, 1,
sheet.getLastColumn()).getValues()[0];
  const obj = {};
  Object.keys(CFG.COLS).forEach(key => {
    const colName = CFG.COLS[key];
    const colIndex = headers[colName];
    if (colIndex) obj[key] = values[colIndex - 1];
  });
  return obj;
}

